import javax.swing.*;import java.awt.*;import java.util.*;
public class App{
 static boolean valid(int[]b,int pos,int value){for(int i=0;i<81;i++)if(i!=pos&&b[i]==value&&(i/9==pos/9||i%9==pos%9||(i/27==pos/27&&i%9/3==pos%9/3)))return false;return true;}
 static int solve(int[]b,int limit){int p=0;while(p<81&&b[p]!=0)p++;if(p==81)return 1;int total=0;for(int v=1;v<=9;v++)if(valid(b,p,v)){b[p]=v;total+=solve(b,limit-total);b[p]=0;if(total>=limit)break;}return total;}
 static boolean fill(int[]b){int p=0;while(p<81&&b[p]!=0)p++;if(p==81)return true;for(int v=1;v<=9;v++)if(valid(b,p,v)){b[p]=v;if(fill(b))return true;b[p]=0;}return false;}
 static int[]puzzle(int seed){int[]b=new int[81];for(int r=0;r<9;r++)for(int c=0;c<9;c++)b[r*9+c]=(r*3+r/3+c)%9+1;Random random=new Random(seed);java.util.List<Integer>cells=new ArrayList<>();for(int i=0;i<81;i++)cells.add(i);Collections.shuffle(cells,random);int removed=0;for(int p:cells){int old=b[p];b[p]=0;if(solve(b.clone(),2)!=1)b[p]=old;else removed++;if(removed==40)break;}return b;}
 public static void main(String[]args){if(args.length>0&&args[0].equals("--self-test")){for(int seed=0;seed<3;seed++){int[]b=puzzle(seed);if(solve(b.clone(),2)!=1||!fill(b))throw new AssertionError();for(int p=0;p<81;p++)if(!valid(b,p,b[p]))throw new AssertionError();}System.out.println("Unique puzzles, solver, and constraints passed");return;}SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Sudoku Studio");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(650,740);JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(20,20,20,20));f.setContentPane(root);JPanel grid=new JPanel(new GridLayout(9,9,2,2));JTextField[]fields=new JTextField[81];int[][]state={puzzle(42)};for(int i=0;i<81;i++){fields[i]=new JTextField();fields[i].setHorizontalAlignment(JTextField.CENTER);fields[i].setFont(new Font("SansSerif",Font.BOLD,24));fields[i].setBackground((i/27+i%9/3)%2==0?new Color(229,242,235):Color.WHITE);grid.add(fields[i]);}root.add(grid,BorderLayout.CENTER);Runnable draw=()->{for(int i=0;i<81;i++){fields[i].setText(state[0][i]==0?"":Integer.toString(state[0][i]));fields[i].setEditable(state[0][i]==0);}};JPanel bar=new JPanel();root.add(bar,BorderLayout.SOUTH);JButton next=new JButton("New puzzle"),check=new JButton("Check entries"),solution=new JButton("Reveal solution");bar.add(next);bar.add(check);bar.add(solution);next.addActionListener(e->{state[0]=puzzle(new Random().nextInt());draw.run();});check.addActionListener(e->{try{int[]b=new int[81];for(int i=0;i<81;i++)b[i]=fields[i].getText().isBlank()?0:Integer.parseInt(fields[i].getText());for(int i=0;i<81;i++)if(b[i]<0||b[i]>9||(b[i]!=0&&!valid(b,i,b[i])))throw new IllegalArgumentException("Conflicting or invalid entry");JOptionPane.showMessageDialog(f,Arrays.stream(b).allMatch(v->v>0)?"Solved!":"No conflicts yet.");}catch(RuntimeException error){JOptionPane.showMessageDialog(f,error.getMessage());}});solution.addActionListener(e->{int[]b=state[0].clone();fill(b);for(int i=0;i<81;i++)fields[i].setText(Integer.toString(b[i]));});draw.run();f.setLocationRelativeTo(null);f.setVisible(true);});}
}
